/**
 * Unit tests for DOMNodePointer.testNode
 */
public class DOMNodePointer_testNode_TriageGen2Test {

    private Node mockElementNode;
    private Node mockTextNode;
    private Node mockCommentNode;
    private Node mockPiNode;
    private Node mockDocNode;
    private Node mockCdataNode;

    @Before
    public void setUp() {
        mockElementNode = mock(Node.class);
        when(mockElementNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(DOMNodePointer.getLocalName(mockElementNode)).thenReturn("localName");
        when(DOMNodePointer.getNamespaceURI(mockElementNode)).thenReturn("http://test.uri");

        mockTextNode = mock(Node.class);
        when(mockTextNode.getNodeType()).thenReturn(Node.TEXT_NODE);

        mockCommentNode = mock(Node.class);
        when(mockCommentNode.getNodeType()).thenReturn(Node.COMMENT_NODE);

        mockPiNode = mock(ProcessingInstruction.class);
        when(mockPiNode.getNodeType()).thenReturn(Node.PROCESSING_INSTRUCTION_NODE);
        when(mockPiNode.getTarget()).thenReturn("targetPI");

        mockDocNode = mock(Node.class);
        when(mockDocNode.getNodeType()).thenReturn(Node.DOCUMENT_NODE);

        mockCdataNode = mock(Node.class);
        when(mockCdataNode.getNodeType()).thenReturn(Node.CDATA_SECTION_NODE);
    }

    @Test
    public void testNullTest() {
        assertTrue(DOMNodePointer.testNode(mockElementNode, null));
    }

    @Test
    public void testNodeNameTest_ElementMismatch() {
        NodeNameTest test = mock(NodeNameTest.class);
        when(test.getNodeName()).thenReturn(new QName("name"));
        // Test with a text node but NodeNameTest requires ELEMENT_NODE
        assertFalse(DOMNodePointer.testNode(mockTextNode, test));
    }

    @Test
    public void testNodeNameTest_WildcardNoPrefix() {
        NodeNameTest test = mock(NodeNameTest.class);
        when(test.isWildcard()).thenReturn(true);
        when(test.getNodeName()).thenReturn(new QName(null, "name", null));

        assertTrue(DOMNodePointer.testNode(mockElementNode, test));
    }

    @Test
    public void testNodeNameTest_WildcardWithPrefix() {
        NodeNameTest test = mock(NodeNameTest.class);
        when(test.isWildcard()).thenReturn(true);
        when(test.getNodeName()).thenReturn(new QName("pref", "name", "http://test.uri"));
        when(test.getNamespaceURI()).thenReturn("http://test.uri");

        assertTrue(DOMNodePointer.testNode(mockElementNode, test));
    }

    @Test
    public void testNodeNameTest_ExactMatchSuccess() {
        NodeNameTest test = mock(NodeNameTest.class);
        when(test.isWildcard()).thenReturn(false);
        when(test.getNodeName()).thenReturn(new QName("pref", "localName", "http://test.uri"));
        when(test.getNamespaceURI()).thenReturn("http://test.uri");

        assertTrue(DOMNodePointer.testNode(mockElementNode, test));
    }

    @Test
    public void testNodeNameTest_ExactMatchNameMismatch() {
        NodeNameTest test = mock(NodeNameTest.class);
        when(test.isWildcard()).thenReturn(false);
        when(test.getNodeName()).thenReturn(new QName("pref", "wrongName", "http://test.uri"));

        assertFalse(DOMNodePointer.testNode(mockElementNode, test));
    }

    @Test
    public void testNodeNameTest_NamespaceMismatch() {
        NodeNameTest test = mock(NodeNameTest.class);
        when(test.isWildcard()).thenReturn(false);
        when(test.getNodeName()).thenReturn(new QName("pref", "localName", "http://wrong.uri"));
        when(test.getNamespaceURI()).thenReturn("http://wrong.uri");

        assertFalse(DOMNodePointer.testNode(mockElementNode, test));
    }

    @Test
    public void testNodeTypeTest() {
        // NODE_TYPE_NODE -> Element or Document
        NodeTypeTest nodeTest = mock(NodeTypeTest.class);
        when(nodeTest.getNodeType()).thenReturn(1); // Compiler.NODE_TYPE_NODE
        assertTrue(DOMNodePointer.testNode(mockElementNode, nodeTest));
        assertTrue(DOMNodePointer.testNode(mockDocNode, nodeTest));
        assertFalse(DOMNodePointer.testNode(mockTextNode, nodeTest));

        // NODE_TYPE_TEXT -> CDATA or Text
        NodeTypeTest textTest = mock(NodeTypeTest.class);
        when(textTest.getNodeType()).thenReturn(2); // Compiler.NODE_TYPE_TEXT
        assertTrue(DOMNodePointer.testNode(mockTextNode, textTest));
        assertTrue(DOMNodePointer.testNode(mockCdataNode, textTest));
        assertFalse(DOMNodePointer.testNode(mockElementNode, textTest));

        // NODE_TYPE_COMMENT
        NodeTypeTest commentTest = mock(NodeTypeTest.class);
        when(commentTest.getNodeType()).thenReturn(3); // Compiler.NODE_TYPE_COMMENT
        assertTrue(DOMNodePointer.testNode(mockCommentNode, commentTest));
        assertFalse(DOMNodePointer.testNode(mockTextNode, commentTest));

        // NODE_TYPE_PI
        NodeTypeTest piTest = mock(NodeTypeTest.class);
        when(piTest.getNodeType()).thenReturn(4); // Compiler.NODE_TYPE_PI
        assertTrue(DOMNodePointer.testNode(mockPiNode, piTest));
        assertFalse(DOMNodePointer.testNode(mockElementNode, piTest));

        // Unknown NodeType
        NodeTypeTest unknownTest = mock(NodeTypeTest.class);
        when(unknownTest.getNodeType()).thenReturn(99);
        assertFalse(DOMNodePointer.testNode(mockElementNode, unknownTest));
    }

    @Test
    public void testProcessingInstructionTest_Success() {
        ProcessingInstructionTest test = mock(ProcessingInstructionTest.class);
        when(test.getTarget()).thenReturn("targetPI");
        assertTrue(DOMNodePointer.testNode(mockPiNode, test));
    }

    @Test
    public void testProcessingInstructionTest_Mismatch() {
        ProcessingInstructionTest test = mock(ProcessingInstructionTest.class);
        when(test.getTarget()).thenReturn("differentPI");
        assertFalse(DOMNodePointer.testNode(mockPiNode, test));
    }

    @Test
    public void testProcessingInstructionTest_WrongNodeType() {
        ProcessingInstructionTest test = mock(ProcessingInstructionTest.class);
        assertFalse(DOMNodePointer.testNode(mockElementNode, test));
    }

    @Test
    public void testUnknownTestType() {
        NodeTest unknown = new NodeTest() {};
        assertFalse(DOMNodePointer.testNode(mockElementNode, unknown));
    }
}

// Mock Interface to allow creating dummy test objects
interface NodeTest {}
